import React from 'react';
import Slider from "react-slick"; // Make sure to install react-slick and slick-carousel

// Import slick-carousel styles
import "slick-carousel/slick/slick.css";
import "slick-carousel/slick/slick-theme.css";

function EventsSlider() {
  const ArrowButton = ({ direction, onClick }) => {
    return (
      <div
        onClick={onClick}
        style={{
          position: "absolute",
          top: "50%",
          [direction]: "-50px",
          transform: "translateY(-50%)",
          backgroundColor: "#FFFF",
          borderRadius: "50%",
          width: "40px",
          height: "40px",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          cursor: "pointer",
          zIndex: 10,
        }}
      >
        <span style={{ color: "#00b666", fontSize: "20px" }}>
          {direction === "left" ? "<" : ">"}
        </span>
      </div>
    );
  };

  const settings = {
    dots: true,
    arrows: true,
    infinite: true,
    autoplay: true,
    autoplaySpeed: 5000,
    slidesToShow: 1,
    slidesToScroll: 1,
    nextArrow: <ArrowButton direction="right" />,
    prevArrow: <ArrowButton direction="left" />,
  };

  return (
    <div style={styles.wrapper}>
      {/* Ek görseller */}
      <div style={styles.shapeDots}>
        <img
          src="assets/shape-dots.svg"
          alt="Dots Shape"
          style={{ width: "50px", height: "50px", marginLeft: "330px" }}
        />
      </div>
      <div style={styles.kesikCizgi}>
        <img
          src="assets/kesik-yan-cizgi.svg"
          alt="Kesik Çizgi"
          style={{ width: "142px", height: "142px", marginRight: "250px" }}
        />
      </div>

      {/* Slider */}
      <div style={styles.content}>
        <Slider {...settings} style={styles.slider}>
          {slides.map((slide, index) => (
            <div key={index} style={styles.contentBox}>
              <a href={slide.url} target="_blank" rel="noopener noreferrer">
                <img src={slide.image} alt={`Slide ${index + 1}`} style={styles.image} />
              </a>
            </div>
          ))}
        </Slider>
      </div>

      {/* Alt Mavi Bar */}
      <div style={styles.bottomBar}></div>
    </div>
  );
}
const styles = {
  wrapper: {
    position: "relative",
    width: "100vw",
    margin: "0 auto",
    backgroundColor: "rgb(246, 248, 255)",
    overflow: "hidden",
  },
  shapeDots: {
    position: "absolute", // Sayfa kaydırıldıkça sabit kalacak
    top: "20px", // Sayfa üstünden 20px uzaklık
    left: "2px", // Sayfa solundan 20px uzaklık
    zIndex: 5, // Diğer öğelerin üstünde kalacak
  },
  kesikCizgi: {
    position: "absolute", // Sayfa kaydırıldıkça sabit kalacak
    top: "20px", // Sayfa altından 20px uzaklık
    right: "20px", // Sayfa sağından 20px uzaklık
    zIndex: 5, // Diğer öğelerin üstünde kalacak
  },
  content: {
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    width: "100%",
    margin: "0",
    position: "relative",
    Opacity: "0.8", // Resmin opaklığı

  },
  slider: {
    width: "100%",
    maxWidth: "1200px",
    margin: "0 auto",
  },
  contentBox: {
    width: "100%",
    height: "400px",
    margin: "0",
    padding: "20px",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    border: "2px solid #e0e0e0", // Hafif bir dış kenar
    borderRadius: "12px", // Köşeler yuvarlak
    boxShadow: "4px 4px 0px 2px rgba(0, 182, 102, 0.6)", // Sağ ve alta yeşil stroke efekti
    backgroundColor: "#fff", // İçerik kutusu beyaz arka plan
    transition: "transform 0.3s ease-in-out", // Hover için animasyon
    cursor: "pointer",
  },
  
  
  image: {
    width: "auto",
    maxHeight: "100%",
    objectFit: "contain",
    borderRadius: "5px",
    boxShadow: "0 4px 8px rgba(0, 0, 0, 0.2)", // Resmin gölgesi
  },
  bottomBar: {
    width: "100%",
    height: "100px",
    backgroundColor: "#293349",
    marginTop: "5px",
  },
};




export default EventsSlider;
